import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

with zipfile.ZipFile('budget.xlsx') as z:
    print("ZIP contents:", z.namelist())
    sheet_xml = z.read('xl/worksheets/sheet1.xml').decode('utf-8')

root = ET.fromstring(sheet_xml)
sheet_data = root.find('m:sheetData', NS)
rows = []
for row in sheet_data.findall('m:row', NS):
    cells = {}
    for c in row.findall('m:c', NS):
        ref = c.get('r')
        t = c.get('t')
        v = c.find('m:v', NS)
        isel = c.find('m:is', NS)
        if t == 'inlineStr' and isel is not None:
            text = ''.join(ts.text or '' for ts in isel.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            cells[ref] = text
        elif v is not None:
            cells[ref] = v.text
    rows.append(cells)

# Print full grid
all_refs = set()
for r in rows:
    all_refs.update(r.keys())

def col_letter(ref):
    return ''.join(ch for ch in ref if ch.isalpha())

def col_num(letter):
    n = 0
    for ch in letter:
        n = n * 26 + (ord(ch) - ord('A') + 1)
    return n

cols = sorted({col_letter(r) for r in all_refs}, key=col_num)
max_row = max((int(''.join(ch for ch in r if ch.isdigit())) for r in all_refs), default=0)

print("\n--- Parsed grid ---")
for rn in range(1, max_row + 1):
    line = []
    for cl in cols:
        val = rows[rn - 1].get(f"{cl}{rn}")
        line.append(f"{cl}{rn}={val!r}" if val is not None else "")
    if any(line):
        print(f"Row {rn}: " + " | ".join(x for x in line if x))
